package com.powercms.cms.publish.entity;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="release_page") @IdClass(ReleasePageEntity.Key.class)
public class ReleasePageEntity { @Id @Column(name="release_id") private UUID releaseId; @Id @Column(name="page_id") private UUID pageId; @Column(name="content_version",nullable=false) private int contentVersion; @Column(name="composition_version") private Integer compositionVersion; @Column(name="route_path",nullable=false,length=1000) private String routePath; @Column(name="html_content",nullable=false,columnDefinition="text") private String htmlContent; @Column(name="input_digest",nullable=false,length=128) private String inputDigest; public static class Key implements java.io.Serializable { public UUID releaseId; public UUID pageId; public Key(){} public Key(UUID r,UUID p){releaseId=r;pageId=p;} public boolean equals(Object o){return o instanceof Key k&&Objects.equals(releaseId,k.releaseId)&&Objects.equals(pageId,k.pageId);} public int hashCode(){return Objects.hash(releaseId,pageId);} } public UUID getReleaseId(){return releaseId;} public void setReleaseId(UUID v){releaseId=v;} public UUID getPageId(){return pageId;} public void setPageId(UUID v){pageId=v;} public int getContentVersion(){return contentVersion;} public void setContentVersion(int v){contentVersion=v;} public Integer getCompositionVersion(){return compositionVersion;} public void setCompositionVersion(Integer v){compositionVersion=v;} public String getRoutePath(){return routePath;} public void setRoutePath(String v){routePath=v;} public String getHtmlContent(){return htmlContent;} public void setHtmlContent(String v){htmlContent=v;} public String getInputDigest(){return inputDigest;} public void setInputDigest(String v){inputDigest=v;} }